/// <summary>
/// MET method to the enable edit button on record
/// </summary>
/// <returns>True if record is not in workflow otherwise false</returns>
public boolean metShouldAllowEdit()
{
    return this.parmRecordsMarked() ? this.parmShouldBeEnabled() && !this.parmInWorkflowReviewOrRejected() : false;
}
